-- Catalog content for the 36 mattress models, from the 2025 KING DAVID
-- catalogue sheet: the marketing copy, the spec list, the feature icons, and
-- the four physical facts the sheet carries per model.
--
-- PRICES ARE NOT TOUCHED. Not the base price, not the per-size supplements,
-- not the variations — the sheet has all of them and this migration reads none
-- of them, so nothing here can move a number a customer is quoted.
--
-- Matching is by NAME, normalised (case, spaces and the various apostrophes
-- removed) against the Hebrew name, the catalogue's longer Hebrew name where
-- it differs, and the English name — whichever the CRM happens to store. A
-- model the CRM does not have is simply not updated, and is listed at the end
-- as a NOTICE.
--
-- The sheet wins where it has something to say, and only there: every column is
-- written with COALESCE, so a filled cell replaces what the CRM had and an
-- empty one leaves it alone. Nothing is ever blanked.

BEGIN;

-- 1. The facts the sheet has that the product had nowhere to keep ----------
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS height_cm      integer,
  ADD COLUMN IF NOT EXISTS no_flip        boolean,
  ADD COLUMN IF NOT EXISTS hardness_label text,
  ADD COLUMN IF NOT EXISTS origin         text;

COMMENT ON COLUMN public.products.height_cm      IS 'גובה המזרן בס"מ, מהקטלוג';
COMMENT ON COLUMN public.products.no_flip        IS 'NO FLIP — מזרן שאינו דורש היפוך';
COMMENT ON COLUMN public.products.hardness_label IS 'דרגת קשיחות כפי שהיא מנוסחת בקטלוג ("קשיח, מפנק במיוחד"), לצד hardness המספרי';
COMMENT ON COLUMN public.products.origin         IS 'ארץ/אופן ייצור כפי שמוצג בקטלוג';

-- 2. Name normalisation and matching ---------------------------------------
-- The CRM's product names are the model plus whatever the shop added around
-- it: "אנרג'י פילוטופ (קשיח ללא קפיצים) (זוגי)", "לידר דו צדדי 2023 (זוגי)",
-- sometimes a leading "מזרן". So a product matches a catalogue model when its
-- normalised name STARTS WITH the model's normalised name, and of all models
-- that fit, the LONGEST wins — which is what keeps "אנרג'י פילוטופ" from
-- falling into plain "אנרג'י", and "לידר גרסת 22 ס״מ" out of plain "לידר".
CREATE FUNCTION pg_temp.catalog_key(t text) RETURNS text
  LANGUAGE sql IMMUTABLE AS $$
    -- Drop parenthesised descriptors, then keep only letters and digits, so
    -- spaces, dashes and the three different apostrophes Hebrew names get
    -- typed with all fall out.
    SELECT regexp_replace(
             lower(regexp_replace(coalesce(t, ''), '\([^)]*\)', '', 'g')),
             '[^a-z0-9\u05d0-\u05ea]', '', 'g')
  $$;

-- Match quality of one candidate model-key against a product key: the key's
-- length when the product starts with it (directly, or after shedding a
-- leading "מזרן"), else 0. An empty candidate never matches anything.
CREATE FUNCTION pg_temp.match_len(pkey text, ckey text) RETURNS int
  LANGUAGE sql IMMUTABLE AS $$
    SELECT CASE
      WHEN ckey IS NULL OR ckey = '' THEN 0
      WHEN pkey LIKE ckey || '%' THEN length(ckey)
      WHEN regexp_replace(pkey, '^מזרן', '') LIKE ckey || '%' THEN length(ckey)
      ELSE 0
    END
  $$;

-- 3. The sheet ------------------------------------------------------------
CREATE TEMP TABLE catalog_import (
  name_he        text,
  alt_he         text,
  name_en        text,
  hardness_label text,
  height_cm      integer,
  warranty_years integer,
  no_flip        boolean,
  description    text,
  features       text,
  technologies   jsonb,
  origin         text
) ON COMMIT DROP;

